 1	import { z } from 'zod';
 2	
 3	const optionalUrl = z
 4	  .url()
 5	  .optional()
 6	  .or(z.literal('').transform(() => undefined));
 7	const environmentSchema = z.object({
 8	  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
 9	  PORT: z.coerce.number().int().min(1).max(65_535).default(3000),
10	  HOST: z.string().min(1).default('0.0.0.0'),
11	  GUEST_SECRET: z.string().min(32).default('development-only-pokewar-guest-secret-change-me'),
12	  CORS_ORIGINS: z.string().default('http://localhost:5173,http://127.0.0.1:5173'),
13	  REDIS_URL: optionalUrl,
14	  REDIS_PREFIX: z.string().min(1).default('pokewar:'),
15	  DATABASE_URL: optionalUrl,
16	});
17	
18	export interface ServerConfig {
19	  readonly nodeEnv: 'development' | 'test' | 'production';
20	  readonly port: number;
21	  readonly host?: string;
22	  readonly guestSecret: string;
23	  readonly corsOrigins: readonly string[];
24	  readonly redisUrl?: string;
25	  readonly redisPrefix: string;
26	  readonly databaseUrl?: string;
27	}
28	
29	export function loadConfig(environment: NodeJS.ProcessEnv = process.env): ServerConfig {
30	  const parsed = environmentSchema.parse(environment);
31	  if (parsed.NODE_ENV === 'production') {
32	    if (parsed.GUEST_SECRET.startsWith('development-only')) {
33	      throw new Error('PRODUCTION_GUEST_SECRET_REQUIRED');
34	    }
35	    if (!parsed.REDIS_URL) throw new Error('PRODUCTION_REDIS_URL_REQUIRED');
36	    if (!parsed.DATABASE_URL) throw new Error('PRODUCTION_DATABASE_URL_REQUIRED');
37	  }
38	  return {
39	    nodeEnv: parsed.NODE_ENV,
40	    port: parsed.PORT,
41	    host: parsed.HOST,
42	    guestSecret: parsed.GUEST_SECRET,
43	    corsOrigins: parsed.CORS_ORIGINS.split(',')
44	      .map((origin) => origin.trim())
45	      .filter(Boolean),
46	    ...(parsed.REDIS_URL ? { redisUrl: parsed.REDIS_URL } : {}),
47	    redisPrefix: parsed.REDIS_PREFIX,
48	    ...(parsed.DATABASE_URL ? { databaseUrl: parsed.DATABASE_URL } : {}),
49	  };
50	}
 1	import { bootstrapServer } from './bootstrap.js';
 2	import { loadConfig } from './config/config.js';
 3	
 4	const config = loadConfig();
 5	const server = await bootstrapServer(config);
 6	
 7	server.httpServer.listen(config.port, config.host ?? '0.0.0.0', () => {
 8	  console.log(
 9	    `[server] PokeWar listening on http://${config.host ?? '0.0.0.0'}:${String(config.port)}`,
10	  );
11	});
12	
13	async function shutdown(signal: string): Promise<void> {
14	  console.log(`[server] received ${signal}, shutting down`);
15	  await server.io.close();
16	  if (server.httpServer.listening) {
17	    await new Promise<void>((resolve, reject) => {
18	      server.httpServer.close((error) => (error ? reject(error) : resolve()));
19	    });
20	  }
21	  await server.closeInfrastructure();
22	}
23	
24	function handleSignal(signal: string): void {
25	  void shutdown(signal).then(
26	    () => process.exit(0),
27	    (error: unknown) => {
28	      console.error('[server] shutdown failed', error);
29	      process.exit(1);
30	    },
31	  );
32	}
33	
34	process.once('SIGINT', () => handleSignal('SIGINT'));
35	process.once('SIGTERM', () => handleSignal('SIGTERM'));
